def find_orfs(seqstr, frame_offset, strand_name):
    """frame_offset 0,1,2 on seqstr; strand_name '+' or '-'"""
    res = []
    n = len(seqstr)
    for off in range(3):
        codons = [seqstr[i:i+3] for i in range(off, n-2, 3)]
        i = 0
        while i < len(codons):
            c = codons[i]
            if c in {'ATG'}:
                # scan to stop
                j = i
                aa = 0
                while j < len(codons):
                    if codons[j] in stops:
                        break
                    j += 1
                naa = j - i  # includes stop? j is first stop index; aa before stop = j-i
                if j < len(codons):
                    # translate everything from i to j (independent of stops inside? none since we break)
                    length_bp = (j - i + 1)*3
                    if (j-i) >= 50:
                        start_pos = off + i*3 + 1  # 1-based in seqstr coords
                        stop_end = off + j*3 + 3
                        res.append((strand_name, off+1, start_pos, stop_end, j-i-1, 'ATG-start'))
                i = j+1
            else:
                i += 1
    return res

def rev_coords_map(seqstr):
