def orfs_in_frame(seqstr, off, strand):
    n = len(seqstr)
    out = []
    i = off
    while i <= n-3:
        if seqstr[i:i+3] == 'ATG':
            j = i
            while j <= n-3 and seqstr[j:j+3] not in stops:
                j += 3
            if j <= n-3:
                naa = (j - i)//3  # codons before stop
                if naa >= 50:
                    if strand == '+':
                        sp = i+1; ep = j+3
                    else:
                        sp = n-(j+3)+1; ep = n-i  # reverse coords in forward frame
                    out.append((strand, sp, ep, naa, 'ATG'))
            i = j+3
        else:
            i += 3
    return out

