best=[]
for strand, seqstr in (('+',s),('-',rc(s))):
    for off in range(3):
        last_stop = off - 3
        for i in range(off, n-2, 3):
            c=seqstr[i:i+3]
            if c in stops:
                length_codons = (i - last_stop)//3
                if length_codons>=50:
                    a=last_stop+3+1; b=i+3
                    if strand=='+':
                        sp,ep=a,b
                    else:
                        sp,ep=n-b+1,n-a+1
                    nt_window = seqstr[last_stop+3:i]
                    atg = seqstr[last_stop+3:last_stop+6]=='ATG'
                    first_atg = nt_window.find('ATG')
                    first_atg_pos = (last_stop+3+first_atg) if first_atg>=0 else None
                    best.append((strand, sp, ep, length_codons, (-1 if atg else last_stop+3+first_atg) ))
                last_stop=i
best_sorted = sorted(best, key=lambda x:-x[3])
print("Top open frames >=50 codons (any start codon):")
for strand, sp, ep, c, atgpos in best_sorted[:15]:
    tag = f"ATG at {atgpos+1}" if atgpos and atgpos>=0 else "no ATG"
    print(f" {strand} {sp}-{ep}: {c} codons  [{tag}]")
